"""Record native successes/failures and the bounded SDK routing correction."""
import hashlib,json,re,shutil
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[1]
save=lambda p,v:p.write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n')

def main():
    pointer=ROOT/'verification/firmware-CD-diagnostic-review.json';review=json.loads(pointer.read_text());out=Path(review['directory'])
    transcript=(out/'native-chat-complete-tests.md').read_text();parts=re.split(r'\n### (System|User|Assistant|Tool)\n',transcript)
    turns=[];current=None
    for i in range(1,len(parts),2):
        role,body=parts[i],parts[i+1]
        if role=='User':current=dict(prompt=body.strip(),messages=[]);turns.append(current)
        elif current:current['messages'].append(dict(role=role,body=body.strip()))
    recent=turns[-4:];assert len(recent)==4
    first=recent[0]['messages'][-1]['body'];repeat=recent[1]['messages'][-1]['body'];fresh=recent[2]['messages'][-1]['body'];ordinary=recent[3]['messages'][-1]['body']
    assert '10,460,888'in first and 'ROM-view-5'in first and '10,460,888'in repeat
    assert not any(x['role']=='Tool'for x in recent[1]['messages'])
    assert all(x in fresh for x in ['447','10,460,873','0x12345678','462','10,460,888'])
    assert all(x in ordinary for x in ['447','10,460,873','0x12345678','0xf1b4c8']) and any(x['role']=='Tool'for x in recent[3]['messages'])
    local=Path(json.loads((ROOT/'verification/easy-firmware-CD-routing-pointer.json').read_text())['directory']);run=json.loads((local/'protocol.json').read_text());item=run['results'][0]
    calls=[c['toolCallRequest']for e in item['events']for c in e['content']if c['type']=='toolCallRequest'];assert len(calls)==1 and calls[0]['arguments']=={'topic':'boot_loader'}
    assert all(x in item['answer']for x in ['447','10,460,873','0x12345678','0x303C']) and not item['quality_flags']
    native=dict(interface='Actual LM Studio native Chat through CUA; exports produced with app UI',history_chat='BIWN — Local Roles and Firmware Checkpoint',current_fresh_chat='BIWN — CD Read Checkpoint',first_response_status='historical/current DSP counts conflated',identical_prompt_repeat_status='no fresh tool call; same incorrect counts',explicit_fresh_scope_comparison_status='counts and boot limits correct',ordinary_question_in_existing_chat_status='fresh tool call; counts and next dependency correct',ordinary_question_in_fresh_chat_status='wrong dsp_media_audio topic; audio-mixer facts incorrectly used for firmware diagnostic',fresh_chat_latest_full_answer_exported=False,fresh_chat_tool_args_verified={'topic':'dsp_media_audio'},fresh_chat_visible_answer_excerpt='Latest DSP diagnostic: the bank1 startup mixer check used 13 supplied SSI word events and 4 timer2 events, producing silence for the default song (startup_music_PCM_nonzero = false); the atomic original-DSP/C regression covers 209 mixer instructions (209/209 selected) including a synthetic type8 sample voice.',fresh_chat_excerpt_is_truncated_AX_observation=True,native_freshness_preset_rule_saved=True,native_explicit_firmware_versus_audio_routing_rule_applied=False,native_routing_retest_pending=True,UI_unavailable_reason='CUA reported Mac locked on final full observation; continue background per user preference, no unlock request.',repeat_response_UI_stats=dict(tokens_per_second=22.37,tokens=212,time_field='0.47s',time_field_semantics_unverified=True,stop_reason='EOS Token Found'),new_weight_training=False,independent_generalization_eval=False)
    save(out/'native-chat-review.json',native);save(out/'native-chat-recent-turns.json',recent)
    sdk=dict(status='ordinary_CD_question_routes_to_boot_loader_and_source_counts_correct',directory=str(local),words=item['words'],seconds=item['seconds'],interface='LM Studio SDK with root preset containing added firmware/audio routing rule',rule_applied_to_native_UI=False,source_review='447 reached instructions/10,460,873 executions/failure12345678 and third-DSP SSI/CD-data/read303C dependency match source evidence.',native_Fresh_chat_failure_not_erased=True,new_weight_training=False,independent_heldout_eval=False)
    save(local/'coordinator-review.json',sdk);save(out/'local-review.json',dict(native=native,SDK=sdk))
    with (out/'who-prompts-and-responses.txt').open('a')as f:
        f.write('\nNATIVE CHAT TESTS — COMPLETE APP EXPORT\n'+transcript+'\nNATIVE COORDINATOR REVIEW\n'+json.dumps(native,indent=2)+'\nSDK ROUTING CORRECTION — EXACT PROMPTS/TOOL RESULT/RESPONSE\n'+(local/'prompts-and-responses.txt').read_text()+'\nSDK SOURCE REVIEW\n'+json.dumps(sdk,indent=2)+'\n')
    review.update(local_review=dict(native=native,SDK=sdk),native_UI_new_test_verified=True,native_UI_broad_reliability_verified=False,native_Game_Assistant_freshness_preset_updated=True,root_Game_Assistant_firmware_routing_updated=True,native_firmware_routing_update_pending=True)
    files=[ROOT/'scripts/clarify_firmware_CD_evidence_scopes.py',ROOT/'scripts/test_firmware_CD_routing.py',ROOT/'scripts/record_firmware_CD_diagnostic_local_review.py',ROOT/'presets/Game Assistant.preset.json',out/'native-chat-before-scope-clarification.md',out/'native-chat-complete-tests.md',out/'native-last-tool-calls.json',out/'native-chat-review.json',out/'native-chat-recent-turns.json',out/'Game-Assistant-preset-before-freshness.json',out/'Game-Assistant-preset-after-freshness.json',local/'protocol.json',local/'prompts-and-responses.txt',local/'coordinator-review.json']
    for i,p in enumerate(files):
        target=out/f'local-{i:02d}-{p.name}';shutil.copy2(p,target);review['manifest'].append(dict(source=str(p),snapshot=str(target),sha256=hashlib.sha256(target.read_bytes()).hexdigest()))
    save(out/'review.json',review);save(pointer,review)
    now=datetime.now(timezone.utc).isoformat();summary=review['evidence']['plain_language_summary']
    for name in ['START HERE.txt','CURRENT DECOMPILATION.txt','CURRENT LOCAL INFERENCE.txt']:shutil.copy2(ROOT/name,out/('prior-'+name))
    (ROOT/'START HERE.txt').write_text(f'''LOCAL AI LAB — START HERE\nUpdated {now}\n\nLOCAL CHAT\nGame Model.command or Advertising Model.command loads advertising-scholar and opens LM Studio. Use Game Assistant or Advertising Assistant with local-ai-lab enabled. Daily model27B/6bit,32,768context,one worker.\nFor current firmware facts, ask: Use project_evidence with topic boot_loader. What is the latest CD boot diagnostic and next read dependency?\n\nSOURCE PROGRESS\n{summary}\n\nVISIBLE NATIVE CHAT TEST\nPrompts/tool calls/responses are visible in “BIWN — Local Roles and Firmware Checkpoint.” Fresh lookup gave correct scope; repeated question initially reused wrong counts. The saved native preset now asks for one fresh status lookup per user turn.\nThe newer “BIWN — CD Read Checkpoint” exposed a wrong audio-topic lookup. Root preset adds explicit firmware/audio routing; SDK retest succeeds, native application of that routing rule and fresh-Chat retest remain pending because the Mac locked. No history was edited or injected.\n{out/'native-chat-complete-tests.md'}\n\nLOCAL SDK CORRECTION\nOrdinary question: one boot_loader lookup, correct50-word answer in {item['seconds']:.2f}seconds. Diagnostic only; no new weight training or broad reliability claim.\n{out/'who-prompts-and-responses.txt'}\n\nADVERTISING\nAnalysis Pilot v2 is trained/exported/loadable but experimental after semantic/rubric/tool-format failures. Base remains default.\n{ROOT/'verification/advertising-analysis-v2-review.json'}\n\nAUDIT/NEXT\n{out/'review.json'}\nFinish source third-DSP SSI/CD-data read, actual header/stub dispatch; validate ROM view/global clocks and remaining game behavior. Apply/test native firmware-topic routing when accessible.\n''')
    current=ROOT/'CURRENT DECOMPILATION.txt';previous=current.read_text();current.write_text(f'DIAGNOSTIC ROM VIEW REACHES SOURCE CD TOC AND PENDING READ\n{now}\n\n{summary}\n\nC/NATIVE CHECK\n447 reached instructions and10,460,873 executions match under supplied DSP-only ROM header5, with original CPU header1 restored before continuation. The source computes failure12345678 itself. This does not establish correct hardware ROM behavior or game authentication. Logical DSP8496bytes compared;233pipeline-tail bytes excluded. Original unchanged-ROM proof462/10,460,888/03D0DEAD remains separate.\n\nFOLLOW-UP\nDeclared controller ticks allow original CPU145,783steps to load TOC DSP; original secondDSP140,371instructions clears header and GO. Original CPU264,208steps loads thirdDSP atF1B020, requests303C read and waits509EC onF1B4C8. Game-stub region does not match the known60000byte payload; no host payload injected.\n\nLOCAL TEST\nNative Chat tests retained: numeric-scope confusion, stale repeat, corrected fresh lookup, correct ordinary lookup in old context, then wrong audio-topic lookup in fresh Chat. Native freshness rule saved; explicit boot-versus-audio routing added to root preset and passed SDK50word/{item["seconds"]:.2f}second retest. Native routing application/retest awaits accessible UI; no unlock requested.\n\nAUDIT\n{out}\n\nNEXT\n{review["evidence"]["next_GPU_CPU_dependency"]["next_action"]}\n\nEARLIER CHECKPOINTS\n'+previous)
    (ROOT/'CURRENT LOCAL INFERENCE.txt').write_text(f'''CURRENT LOCAL INFERENCE\nUpdated {now}\n\nDaily advertising-scholar27B/6bit,32,768context,one worker; weights/model unchanged. Game Assistant freshness rule saved in native UI. Root Game Assistant also has explicit firmware boot/DSP diagnostics->boot_loader routing; that extra rule is not yet applied or retested natively.\n\nNATIVE CHAT\n“BIWN — Local Roles and Firmware Checkpoint” contains visible prompts/evidence/answers. First response mixed historical/current counts; same question reused old answer without tool; explicitly fresh lookup separated counts correctly; an ordinary question in existing context also succeeded. A fresh “BIWN — CD Read Checkpoint” selected dsp_media_audio and answered with the unrelated startup mixer. This failure is retained, not counted as success. Mac locked before full fresh-Chat export; actual MCP tool log confirms wrong topic.\n{out/'native-chat-complete-tests.md'}\n{out/'native-chat-review.json'}\n\nSDK ROUTING RETEST\nSame ordinary question with root routing rule: one boot_loader call, correct50word answer in {item['seconds']:.2f}seconds. This is adaptive diagnostic testing on the same weights/source, not independent reliability or training.\n{out/'who-prompts-and-responses.txt'}\n{out/'local-review.json'}\n\nSOURCE\n{summary}\n\nADVERTISING\nPilot v2 trained/exported/loadable but experimental; base remains active.\n{ROOT/'verification/advertising-analysis-v2-review.json'}\n\nNEXT\nApply root firmware-topic routing to native preset and retest fresh Chat when accessible; continue source third-DSP SSI/CD read and full-game work while locked. Future256GB profile remains unbenchmarked; full goal incomplete.\n''')
    for name in ['START HERE.txt','CURRENT DECOMPILATION.txt','CURRENT LOCAL INFERENCE.txt']:shutil.copy2(ROOT/name,out/('current-'+name))
    p=ROOT/'verification/NEXT SOURCE AND INFERENCE WORK.json';n=json.loads(p.read_text());n.update(local_audit=str(out),local_roles_this_turn=review['local_review'],last_turn_classification='progress',new_training_this_turn=False,native_firmware_routing_update_pending=True);save(p,n)
    (ROOT/'training/feedback/firmware-CD-native-routing-20261015.jsonl').write_text(json.dumps(dict(native=native,SDK=sdk,used_in_weight_training=False))+'\n')
    assert all(hashlib.sha256(Path(x['snapshot']).read_bytes()).hexdigest()==x['sha256']for x in review['manifest'])
    print(json.dumps(dict(audit=str(out),native_fresh_lookup_correct=True,native_fresh_chat_routing_correct=False,SDK_routing_correct=True,SDK_words=item['words'],SDK_seconds=item['seconds'],whole_goal_complete=False)))

if __name__=='__main__':main()
